fn forward_transfer_status(
    crate_rx: &std::sync::mpsc::Receiver<SsDownloadStatus>,
    forward_tx: &tokio::sync::mpsc::Sender<DownloadStatus>,
    forward_cancelled: &AtomicBool,
    interactive: bool,
