pub(crate) fn normalize_catalog_key(value: &str) -> String {
    // The filter runs on BOTH sides of the compatibility fold. Before it, so a
    // mark that decomposes into something else is removed while it is still one
    // character (U+00B4 becomes a space plus a combining acute). After it, so a
    // compatibility variant that NFKC turns INTO a listed mark is removed too:
    // U+FF07 (fullwidth apostrophe) folds to U+0027, which the first pass could
    // not see. Without the second pass a fullwidth keyboard tag keeps its own
    // key and the same artist or album is treated as two.
    value
        .chars()
        .filter(|character| !APOSTROPHE_LIKE_CHARACTERS.contains(character))
        .collect::<String>()
        .nfkc()
        .filter(|character| !APOSTROPHE_LIKE_CHARACTERS.contains(character))
        .collect::<String>()
        .flat_map(char::to_lowercase)
        .collect::<String>()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}

