    // non-empty placeholder, which must satisfy that title too.
    let placeholder = build_index(&[scanned("Artist", "_")]);
    assert!(
        placeholder.contains_album("Artist", "???"),
        "the placeholder folder must satisfy the title it replaced"
    );
}

