    let mode_key = serde_yaml::Value::String("default_mode".into());
    let Some(serde_yaml::Value::String(value)) = search.get_mut(&mode_key) else {
        return false;
    };
    if value.trim() != "auto" {
        return false;
    }
    *value = "upgrade".to_string();
    true
}
