import re, collections, pathlib

FILES = ["src/mode.rs","src/config.rs","src/main.rs","src/runner.rs",
         "tests/mode_resolution_test.rs","tests/pipeline_test.rs"]

def tests_in(text):
    out=[]
    for m in re.finditer(r'\n    (?:async )?fn ([a-z0-9_]+)\(\)[^{]*\{(.*?)\n    \}\n', text, re.S):
        out.append((m.group(1), m.group(2)))
    # integration tests are top-level (no indentation)
    for m in re.finditer(r'\n(?:async )?fn ([a-z0-9_]+)\(\)[^{]*\{(.*?)\n\}\n', text, re.S):
        out.append((m.group(1), m.group(2)))
    return out

def asserts(body):
    """Every assert statement's full text, whitespace-normalised."""
    out=[]
    for m in re.finditer(r'assert(?:_eq|_ne)?!?\(', body):
        i=m.start(); depth=0
        for j in range(i, len(body)):
            if body[j]=='(': depth+=1
            elif body[j]==')':
                depth-=1
                if depth==0:
                    out.append(re.sub(r'\s+',' ',body[i:j+1])); break
    return out

registry={}
for f in FILES:
    p=pathlib.Path(f)
    if not p.exists(): continue
    for name, body in tests_in(p.read_text()):
        registry.setdefault(name, []).append((f, asserts(body)))

print(f"tests inspected (name, file, #asserts): {len(registry)}")
by_sig=collections.defaultdict(list)
for name, entries in registry.items():
    for f, sig in entries:
        by_sig[tuple(sorted(sig))].append(f"{f}::{name}")

print("\n=== EXACT duplicate assertion sets (candidate duplicates) ===")
found=False
for sig, names in by_sig.items():
    if len(names) > 1 and sig:
        found=True
        print(f"  {len(names)} tests share {len(sig)} identical asserts:")
        for n in names: print(f"     {n}")
if not found: print("  none")

print("\n=== SUBSET relationships (one test's asserts all appear in another) ===")
